        }}

class GuardrailsEngine:
    def audit_ast_and_secrets(self, file_path: str, code_content: str) -> tuple[bool, list[str]]:
        # Line 21-25: Multi-vendor credential scan + AST syntax parser
        ast.parse(code_content, filename=file_path)
        if re.search(r"(sk-proj-[A-Za-z0-9_\-]{20,}|AKIA[0-9A-Z]{16})", code_content):
            return False, ["CRITICAL: Hardcoded API secret key detected!"]
        return True, ["AST syntax valid. Zero secrets."]

class PermissionEscalationGateway:
    def evaluate_request(self, tool_name: str, params: dict, request_id: str) -> dict:
        risk = self.risk_matrix.get(tool_name, "HIGH")

        # Line 5-7: LOW risk (reads) -> Auto-approved
        if risk == "LOW":
            return {"allowed": True, "content": (self.workspace / params["path"]).read_text("utf-8")}

        # Line 9-11: MEDIUM risk (writes) -> Logged and executed in sandbox
        if risk == "MEDIUM":
            (self.workspace / params["path"]).write_text(params["content"], encoding="utf-8")
            return {"allowed": True, "path": str(self.workspace / params["path"])}

        # Line 13-20: CRITICAL risk (git_push) -> Strictly gated by approvals.json
        if risk == "CRITICAL":
            approvals = self._approvals()  # reads approvals.json
            if request_id not in approvals:
                self._log({"event": "ESCALATION_BLOCKED", "request_id": request_id})
                return {"allowed": False, "reason": "missing_approval"}
            pending = {"request_id": request_id, "approved_by": approvals[request_id]}
            (self.workspace / "pending_push.json").write_text(json.dumps(pending, indent=2), encoding="utf-8")
            return {"allowed": True, "pending_push": str(self.workspace / "pending_push.json")}

class TDAReliabilityPipeline:
    def run_test_suite(self, code_under_test: str) -> dict:
        self.code_file.write_text(code_under_test, encoding="utf-8")
        # Line 4-9: Real pytest subprocess with isolated environment
        result = subprocess.run(
            [sys.executable, "-m", "pytest", self.test_file.name, "-q", "--tb=short", "-p", "no:cacheprovider"],
            cwd=self.scratch_dir, capture_output=True, text=True, encoding="utf-8",
            env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"}
        )
        output = result.stdout + (result.stderr or "")
        # Line 12-14: Non-zero exit code captures traceback for prompt feedback
        if result.returncode != 0:
            return {"passed": False, "traceback": output, "returncode": result.returncode}
        return {"passed": True, "summary": self._summary_line(output)}

    def register_anti_regression_test(self, bug_name: str, test_code: str) -> dict:
        # Line 18-20: Discovered bugs permanently append to test suite
        with self.test_file.open("a", encoding="utf-8") as handle:
            handle.write(f"\n\n{test_code.rstrip()}\n")
        return self.run_test_suite(self.code_file.read_text(encoding="utf-8"))
